import java.io.*;
import java.util.*;

class Book {
    String title;
    String author;
    String bookID;
    boolean borrowed;

    public Book(String title, String author, String bookID) {
        this.title = title;
        this.author = author;
        this.bookID = bookID;
        this.borrowed = false;
    }
}

class Library {
    List<Book> books;

    public Library() {
        books = new ArrayList<>();
    }

    public boolean addBook(String title, String author, String bookID) {
        for (Book book : books) {
            if (book.bookID.equals(bookID)) {
                return false;
            }
        }
        books.add(new Book(title, author, bookID));
        return true;
    }

    public boolean borrowBook(String bookID) {
        for (Book book : books) {
            if (book.bookID.equals(bookID)) {
                if (book.borrowed) {
                    return false;
                }
                book.borrowed = true;
                return true;
            }
        }
        return false;
    }

    public boolean returnBook(String bookID) {
        for (Book book : books) {
            if (book.bookID.equals(bookID)) {
                book.borrowed = false;
                return true;
            }
        }
        return false;
    }
}

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        Library library = new Library();
        String line;

        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) {
                continue;
            }

            String[] parts = parseCommand(line);
            if (parts == null) {
                continue;
            }

            String command = parts[0].toLowerCase();

            switch (command) {
                case "add":
                    if (parts.length >= 4) {
                        String title = parts[1];
                        String author = parts[2];
                        String bookID = parts[3];
                        if (library.addBook(title, author, bookID)) {
                            System.out.println("Book added successfully.");
                        } else {
                            System.out.println("Error: Book with ID " + bookID + " already exists.");
                        }
                    } else {
                        System.out.println("Error: Invalid add command.");
                    }
                    break;

                case "borrow":
                    if (parts.length >= 2) {
                        String bookID = parts[1];
                        if (library.borrowBook(bookID)) {
                            System.out.println("Book borrowed successfully.");
                        } else {
                            system.out.println("Error: Cannot borrow book with ID " + bookID + ".");
                        }
                    } else {
                        System.out.println("Error: Invalid borrow command.");
                    }
                    break;

                case "return":
                    if (parts.length >= 2) {
                        String bookID = parts[1];
                        if (library.returnBook(bookID)) {
                            System.out.println("Book returned successfully.");
                        } else {
                            System.out.println("Error: Book with ID " + bookID + " not found.");
                        }
                    } else {
                        System.out.println("Error: Invalid return command.");
                    }
                    break;

                default:
                    System.out.println("Error: Unknown command.");
            }
        }
    }

    private static String[] parseCommand(String line) {
        String trimmed = line.trim();
        if (trimmed.isEmpty()) {
            return null;
        }

        String[] result = new String[4];
        int index = 0;
        int pos = 0;

        // First, find the command (first word)
        while (pos < trimmed.length() && Character.isWhitespace(trimmed.charAt(pos))) {
            pos++;
        }

        while (pos < trimmed.length() && !Character.isWhitespace(trimmed.charAt(pos))) {
            pos++;
        }

        result[0] = trimmed.substring(0, pos);

        // Now parse quoted strings
        while (pos < trimmed.length()) {
            // Skip whitespace
            while (pos < trimmed.length() && Character.isWhitespace(trimmed.charAt(pos))) {
                pos++;
            }

            if (pos >= trimmed.length()) {
                break;
            }

            if (trimmed.charAt(pos) == '"') {
                pos++; // skip opening quote
                int start = pos;
                while (pos < trimmed.length() && trimmed.charAt(pos) != '"') {
                    pos++;
                }
                String value = trimmed.substring(start, pos);
                if (index < 3) {
                    result[index + 1] = value;
                }
                if (pos < trimmed.length()) {
                    pos++; // skip closing quote
                }
                index++;
            } else {
                // Non-quoted string (like bookID for borrow/return)
                int start = pos;
                while (pos < trimmed.length() && trimmed.charAt(pos) != '"') {
                    pos++;
                }
                String value = trimmed.substring(start, pos).trim();
                if (index < 3) {
                    result[index + 1] = value;
                }
                index++;
            }
        }

        // Adjust result array size based on command
        if ("add".equalsIgnoreCase(result[0])) {
            return Arrays.copyOf(result, 4);
        } else {
            return Arrays.copyOf(result, 2);
        }
    }
}
